$content = Get-Content "C:\Users\PATI Work\Documents\PATI Work\Adlauncher Apps\New-Ads-Launcher\app\(dashboard)\launch\page.tsx" -Raw
$content = $content -replace '(?s)  const \[uploading, setUploading\] = useState\(false\)\n  const \[uploadProgress, setUploadProgress\] = useState<\{ current: number; total: number \} \| null>\(null\)\n  const \[uploadPauseMsg, setUploadPauseMsg\] = useState<string \| null>\(null\)\n  const uploadFileRef = useRef<HTMLInputElement>\(null\)\n  const uploadFolderRef = useRef<HTMLInputElement>\(null\)', ''
$content = $content -replace '(?s)  // ── Google Drive state ──────────────────────────────────────────\n  // Short-lived memory cache — server is the source of truth for refresh tokens.*?// ── Google Drive Picker ──────────────────────────────────────────\n  const loadGoogleScript =.*?const TABS', '  const TABS'
$content = $content -replace '(?s)\n              \{uploadPauseMsg && \(\n                <span className="text-xs text-amber-600 dark:text-amber-400 flex items-center gap-1 mr-1">\n                  \{uploading\n                    \? <IconLoader2 className="size-3 animate-spin" />\n                    : <IconCheck className="size-3" />\n                  \}\n                  \{uploadPauseMsg\}\n                </span>\n              \)\}\n              <Button variant="outline" size="sm" className="gap-1.5" onClick=\{\(\) => uploadFileRef.current\?\.click\(\)\} disabled=\{uploading\}>\n                \{uploading && uploadProgress\n                  \? <><IconLoader2 className="size-3.5 animate-spin" />\{uploadProgress.current\}/\{uploadProgress.total\}</>\n                  : <><IconUpload className="size-3.5" />Upload New Media</>\n                \}\n              </Button>\n              <Button variant="outline" size="sm" className="gap-1.5" onClick=\{\(\) => uploadFolderRef.current\?\.click\(\)\} disabled=\{uploading\}>\n                <IconFolder className="size-3.5" />Upload Folder\n              </Button>', ''
$content = $content -replace '(?s)        \) : mediaTab === "drive_link" \? \(.*?</DialogContent>', '</DialogContent>'
$content = $content -replace '  const TABS: \{ id: MediaTab; label: string; Icon: React\.ElementType; beta\?: boolean \}\[\] = \[\n    \{ id: "library", label: "Media Library", Icon: IconStack2 \},\n    \{ id: "existing", label: "Existing Ads", Icon: IconLayoutGrid \},\n    \{ id: "gdrive", label: "Google Drive", Icon: IconBrandGoogleDrive \},\n    \{ id: "drive_browser", label: "Drive Browser", Icon: IconBrandGoogleDrive, beta: true \},\n    \{ id: "drive_link", label: "Drive Link", Icon: IconBrandGoogleDrive \},\n    \{ id: "integrations", label: "Integrations", Icon: IconSettings \},\n  \]', "  const TABS: { id: MediaTab; label: string; Icon: React.ElementType; beta?: boolean }[] = [`n    { id: `"library`", label: `"Media Library`", Icon: IconStack2 },`n    { id: `"existing`", label: `"Existing Ads`", Icon: IconLayoutGrid },`n  ]"
$content | Set-Content "C:\Users\PATI Work\Documents\PATI Work\Adlauncher Apps\New-Ads-Launcher\app\(dashboard)\launch\page.tsx" -Encoding utf8
